#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

int main() {
    int n;
    if (cin >> n) {
        vector<int> a(n + 1), sum(n + 1, 0);
        for(int i = 1; i <= n; ++i) {
            cin >> a[i];
            sum[i] = sum[i-1] + a[i]; // 计算前缀和
        }

        vector<vector<int>> dp(n + 1, vector<int>(n + 1, 0));

        // len 为区间长度，从 2 开始枚举
        for(int len = 2; len <= n; ++len) {
            for(int i = 1; i + len - 1 <= n; ++i) {
                int j = i + len - 1;
                dp[i][j] = INT_MAX;
                // 枚举分割点 k
                for(int k = i; k < j; ++k) {
                    int cost = dp[i][k] + dp[k+1][j] + (sum[j] - sum[i-1]);
                    dp[i][j] = min(dp[i][j], cost);
                }
            }
        }
        cout << dp[1][n] << "\n";
    }
    return 0;
}
